// Herramienta de un solo uso: inserta datos de ejemplo en stock sin borrar datos existentes.
// Uso: go run ./cmd/seed  (desde el directorio backend/)
package main

import (
	"fmt"
	"log"

	"nutriclinica/internal/config"
	"nutriclinica/internal/store"
)

func main() {
	pgCfg, err := config.PostgresFromEnv()
	if err != nil {
		log.Fatalf("configuración de PostgreSQL: %v", err)
	}
	st, err := store.Open(pgCfg)
	if err != nil {
		log.Fatalf("abriendo BD: %v", err)
	}
	defer st.Close()

	stmts := seedSQL()
	for _, sql := range stmts {
		if _, err := st.DB.Exec(sql); err != nil {
			log.Fatalf("ejecutando SQL:\n%s\nError: %v", sql, err)
		}
	}

	fmt.Println("✓ Datos de ejemplo insertados correctamente.")
}

